import{_ as e,o as d,c as r,aj as a}from"./chunks/framework.Dp4IQB_f.js";const u=JSON.parse('{"title":"Compared with other libraries","description":"","frontmatter":{},"headers":[],"relativePath":"guide/benchmarks.md","filePath":"guide/benchmarks.md"}'),o={name:"guide/benchmarks.md"};function s(i,t,n,h,c,l){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="compared-with-other-libraries" tabindex="-1">Compared with other libraries <a class="header-anchor" href="#compared-with-other-libraries" aria-label="Permalink to &quot;Compared with other libraries&quot;">​</a></h1><p>Measured with <code>npm run bench:versus</code> on public data (Spotify song titles, the 20,000 most common English words, 151,000 world cities), Node 22, median of 7 runs. Every library gets the same inputs. Run it yourself: the numbers move a little from one machine to another.</p><h2 id="string-similarity" tabindex="-1">string-similarity <a class="header-anchor" href="#string-similarity" aria-label="Permalink to &quot;string-similarity&quot;">​</a></h2><p><code>fuzzy-toolkit/string-similarity</code> returns exactly the same numbers as <code>string-similarity</code> (checked on 20,000 real pairs and thousands of random ones in the tests).</p><table tabindex="0"><thead><tr><th>Task</th><th>string-similarity</th><th>fuzzy-toolkit</th><th></th></tr></thead><tbody><tr><td><code>compareTwoStrings</code>, 20,000 title pairs</td><td>45 ms</td><td>22 ms</td><td><strong>2× faster</strong></td></tr><tr><td><code>findBestMatch</code>, 1,000 queries × 2,000 titles</td><td>4.0 s</td><td>1.2 s</td><td><strong>3.2× faster</strong></td></tr></tbody></table><h2 id="did-you-mean" tabindex="-1">&quot;Did you mean…?&quot; <a class="header-anchor" href="#did-you-mean" aria-label="Permalink to &quot;&quot;Did you mean…?&quot;&quot;">​</a></h2><p>500 misspelled words against the 20,000 most common English words.</p><table tabindex="0"><thead><tr><th></th><th>Right word</th><th>Time</th></tr></thead><tbody><tr><td>string-similarity <code>findBestMatch</code></td><td>39.0 %</td><td>6.9 s</td></tr><tr><td>fuzzy-toolkit <code>createIndex(words).closest()</code></td><td><strong>93.4 %</strong></td><td><strong>0.21 s</strong> (33× faster)</td></tr></tbody></table><h2 id="search-as-you-type" tabindex="-1">Search as you type <a class="header-anchor" href="#search-as-you-type" aria-label="Permalink to &quot;Search as you type&quot;">​</a></h2><p>300 typed queries (the start of a title, with a typo) over 23,450 song titles, top 10.</p><table tabindex="0"><thead><tr><th></th><th>Wanted title found</th><th>Time per query</th></tr></thead><tbody><tr><td>Fuse.js</td><td>65.3 %</td><td>81.6 ms</td></tr><tr><td>fuzzysort</td><td>21.7 %</td><td>0.8 ms</td></tr><tr><td>fuzzy-toolkit <code>createIndex(titles, { preset: &#39;search&#39; })</code></td><td><strong>82.7 %</strong></td><td>11.0 ms</td></tr></tbody></table><p>fuzzysort is the fastest but only matches letters in order, so a typo loses the result. fuzzy-toolkit finds more than Fuse.js, 7 times faster.</p><h2 id="acronyms" tabindex="-1">Acronyms <a class="header-anchor" href="#acronyms" aria-label="Permalink to &quot;Acronyms&quot;">​</a></h2><p>150 city names of 3 words or more typed as their initials (<code>nyc</code>), among 151,186 cities, top 10.</p><table tabindex="0"><thead><tr><th></th><th>Found</th><th>Time per query</th></tr></thead><tbody><tr><td>match-sorter</td><td>59.3 %</td><td>104 ms</td></tr><tr><td>fuzzy-toolkit <code>createIndex(cities, { preset: &#39;search&#39; })</code></td><td><strong>82.0 %</strong></td><td><strong>19 ms</strong></td></tr></tbody></table><h2 id="levenshtein-distance" tabindex="-1">Levenshtein distance <a class="header-anchor" href="#levenshtein-distance" aria-label="Permalink to &quot;Levenshtein distance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pairs</th><th>fastest-levenshtein</th><th>fuzzy-toolkit <code>levenshtein</code></th></tr></thead><tbody><tr><td>20,000 titles + 20,000 words</td><td>24.7 ms</td><td><strong>15.0 ms</strong> (1.6×)</td></tr><tr><td>2,000 sentences of 100-400 characters, with typos</td><td>25.1 ms</td><td><strong>11.9 ms</strong> (2.1×)</td></tr></tbody></table><p><code>damerau</code> (swapped letters count once) costs about the same: 12.4 ms on the sentences.</p><h2 id="dedupe" tabindex="-1">Dedupe <a class="header-anchor" href="#dedupe" aria-label="Permalink to &quot;Dedupe&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Time</th></tr></thead><tbody><tr><td><code>dedupe()</code>, 5,000 song titles, typos included</td><td>1.1-1.4 s (4.5 s in v2.1)</td></tr><tr><td><code>dedupe(..., { method: &#39;fingerprint&#39; })</code>, 20,000 titles</td><td>113 ms</td></tr></tbody></table><h2 id="saved-index" tabindex="-1">Saved index <a class="header-anchor" href="#saved-index" aria-label="Permalink to &quot;Saved index&quot;">​</a></h2><p>151,186 cities: <code>createIndex</code> takes 318 ms, <code>loadIndex</code> from JSON 155 ms. Fuse.js builds its (lighter) index in 31 ms, but searches it 5 to 10 times slower.</p><h2 id="size" tabindex="-1">Size <a class="header-anchor" href="#size" aria-label="Permalink to &quot;Size&quot;">​</a></h2><p>Minified and gzipped, with <code>npm run size</code>:</p><table tabindex="0"><thead><tr><th>Import</th><th>Size</th></tr></thead><tbody><tr><td><code>levenshtein</code>, <code>damerau</code></td><td>1.3 kB</td></tr><tr><td><code>fuzzy-toolkit/string-similarity</code></td><td>0.8 kB</td></tr><tr><td><code>similarity</code>, <code>isMatch</code></td><td>7.1 kB</td></tr><tr><td><code>check</code>, <code>checkAll</code></td><td>7.8 kB</td></tr><tr><td><code>createIndex</code>, <code>search</code>, <code>highlight</code></td><td>9.7 kB</td></tr><tr><td>everything</td><td>13.4 kB</td></tr></tbody></table>',25)])])}const b=e(o,[["render",s]]);export{u as __pageData,b as default};
